impl<T: gx::Coef> Odd<(), T> {
    /// A value from its coefficients, in blade order.
    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(e0: T, e1: T, e2: T, e3: T, e123: T, e032: T, e013: T, e021: T) -> Self {
        Odd { c: [e0, e1, e2, e3, e123, e032, e013, e021] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
    #[inline(always)]
    pub fn prepare<X>(self) -> <Self as gx::Prepare<X>>::Output
    where
        Self: gx::Prepare<X>,
    {
        gx::Prepare::prepare(self)
    }

    /// The identity map on `Odd`: a `Odd` with one open `Odd` slot.
    #[inline(always)]
    pub fn slot() -> Odd<(Odd,), T> {
        Odd { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e0`.
    #[inline(always)]
    pub fn e0(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e1`.
    #[inline(always)]
    pub fn e1(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e2`.
    #[inline(always)]
    pub fn e2(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e3`.
    #[inline(always)]
    pub fn e3(&self) -> T {
        self.c[3]
    }

    /// Coefficient of `e123`.
    #[inline(always)]
    pub fn e123(&self) -> T {
        self.c[4]
    }

    /// Coefficient of `e032`.
    #[inline(always)]
    pub fn e032(&self) -> T {
        self.c[5]
    }

    /// Coefficient of `e013`.
    #[inline(always)]
    pub fn e013(&self) -> T {
        self.c[6]
    }

    /// Coefficient of `e021`.
    #[inline(always)]
    pub fn e021(&self) -> T {
        self.c[7]
    }
}

