impl<T: gx::Real> Multivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t5 = x[5] * x[5];
        let t7 = x[7] * x[7];
        let t9 = x[9] * x[9];
        let t12 = x[12] * x[12];
        let t14 = x[14] * x[14];
        let t15 = x[15] * x[15];
        let t16 = x[0].mul_add(x[0], t1);
        let t17 = x[8].mul_add(x[8], t9);
        let t18 = t16 + t17;
        let t19 = x[10].mul_add(x[10], t12);
        let t20 = x[13].mul_add(x[13], t14);
        let t21 = t19 + t20;
        let t22 = t18 + t21;
        let t23 = x[2].mul_add(x[2], t3);
        let t24 = x[4].mul_add(x[4], t5);
        let t25 = t23 + t24;
        let t26 = x[6].mul_add(x[6], t7);
        let t27 = x[11].mul_add(x[11], t15);
        let t28 = t26 + t27;
        let t29 = t25 + t28;
        let t30 = t22 - t29;
        t30
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

